ALTER TABLE "coding_tasks" DROP CONSTRAINT "chk_coding_tasks_queued_bare";--> statement-breakpoint
ALTER TABLE "coding_tasks" DROP CONSTRAINT "chk_coding_tasks_plan_at_gate";--> statement-breakpoint
ALTER TABLE "coding_tasks" DROP CONSTRAINT "chk_coding_tasks_approval_after_gate";--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD COLUMN "presubmit_fix_passes" smallint DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD CONSTRAINT "chk_coding_tasks_fix_passes_bound" CHECK ("coding_tasks"."presubmit_fix_passes" BETWEEN 0 AND 2);--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD CONSTRAINT "chk_coding_tasks_fix_owed" CHECK ("coding_tasks"."status" <> 'pending_fix' OR (COALESCE("coding_tasks"."presubmit_verdict"->>'kind' = 'refused', false) AND "coding_tasks"."presubmit_fix_passes" >= 1));--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD CONSTRAINT "chk_coding_tasks_queued_bare" CHECK ("coding_tasks"."status" <> 'queued' OR ("coding_tasks"."worktree_assignment" IS NULL AND "coding_tasks"."session_id" IS NULL AND "coding_tasks"."container_id" IS NULL AND "coding_tasks"."plan" IS NULL AND "coding_tasks"."plan_approved_at" IS NULL AND "coding_tasks"."pr_metadata" IS NULL AND "coding_tasks"."resource_usage" IS NULL AND "coding_tasks"."claimed_by_run_id" IS NULL AND "coding_tasks"."presubmit_verdict" IS NULL AND "coding_tasks"."presubmit_fix_passes" = 0));--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD CONSTRAINT "chk_coding_tasks_plan_at_gate" CHECK ("coding_tasks"."status" NOT IN ('awaiting_approval', 'executing', 'pending_verify', 'verifying', 'pending_fix', 'pushed', 'pr_open') OR "coding_tasks"."plan" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "coding_tasks" ADD CONSTRAINT "chk_coding_tasks_approval_after_gate" CHECK (("coding_tasks"."plan_approved_at" IS NULL OR "coding_tasks"."status" <> 'planning') AND ("coding_tasks"."status" NOT IN ('executing', 'pending_verify', 'verifying', 'pending_fix', 'pushed', 'pr_open') OR "coding_tasks"."plan_approved_at" IS NOT NULL));